package example

import (
    context "context"

    management "github.com/auth0/go-auth0/v3/management"
    client "github.com/auth0/go-auth0/v3/management/client"
    option "github.com/auth0/go-auth0/v3/management/option"
)

func do() {
    mgmt, err := client.New(
        "{YOUR_DOMAIN}",
        option.WithToken(
            "<token>",
        ),
    )
    if err != nil {
        return
    }
    request := &management.ListActionsRequestParameters{
        TriggerId: management.String(
            "triggerId",
        ),
        ActionName: management.String(
            "actionName",
        ),
        Deployed: management.Bool(
            true,
        ),
        Page: management.Int(
            1,
        ),
        PerPage: management.Int(
            1,
        ),
        Installed: management.Bool(
            true,
        ),
    }
    mgmt.Actions.List(
        context.TODO(),
        request,
    )
}

