        ManagementApi client = ManagementApi
            .builder()
            .domain("{YOUR_DOMAIN}")
            .token("<token>")
            .build();

        client.actions().create(
            CreateActionRequestContent
                .builder()
                .name("name")
                .supportedTriggers(
                    Arrays.asList(
                        ActionTrigger
                            .builder()
                            .id(ActionTriggerTypeEnum.POST_LOGIN)
                            .build()
