package com.example.usage;

import com.auth0.client.mgmt.ManagementApi;
import com.auth0.client.mgmt.keys.types.SetCustomSigningKeysRequestContent;
import com.auth0.client.mgmt.types.CustomSigningKeyJwk;
import com.auth0.client.mgmt.types.CustomSigningKeyTypeEnum;
import java.util.Arrays;

public class Example {
    public static void main(String[] args) {
        ManagementApi client = ManagementApi
            .builder()
            .domain("{YOUR_DOMAIN}")
            .token("<token>")
            .build();

        client.keys().customSigning().set(
            SetCustomSigningKeysRequestContent
                .builder()
                .keys(
                    Arrays.asList(
                        CustomSigningKeyJwk
                            .builder()
                            .kty(CustomSigningKeyTypeEnum.EC)
                            .build()
                    )
                )
                .build()
        );
    }
}

